mapper.select:
SELECT po.*, pt.name as patient_name, p.prescription_no, u.real_name as processor_name FROM processing_order po LEFT JOIN prescription p ON po.prescription_id = p.id LEFT JOIN patient pt ON p.patient_id = pt.id LEFT JOIN sys_user u ON po.processor_id = u.id
AND (pt.name LIKE CONCAT('%', #{keyword}, '%') OR po.order_no LIKE CONCAT('%', #{keyword}, '%'))
AND po.status = #{status}
ORDER BY CASE po.status WHEN 'PENDING' THEN 0 WHEN 'PROCESSING' THEN 1 WHEN 'QUALITY_CHECK' THEN 2 ELSE 3 END, po.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM processing_order po LEFT JOIN prescription p ON po.prescription_id = p.id LEFT JOIN patient pt ON p.patient_id = pt.id
AND (pt.name LIKE CONCAT('%', #{keyword}, '%') OR po.order_no LIKE CONCAT('%', #{keyword}, '%'))
AND po.status = #{status}
